const PLACE_IMAGE_BY_ID = {
  'dragon-bridge': danangDragonBridge,
  'ba-na-hills': danangBaNa,
  'son-tra': danangSonTra,
  'ngu-hanh-son': danangNguHanhSon,
  'my-khe-beach': cityLandmark,
  'han-market': cityFood,
  'cham-museum': cityLandmark,
  'hai-van-pass': cityRoute
};

function PlaceListPage() {
  const { language } = useLanguage();
  const { theme } = useTheme();
  const [places, setPlaces] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');

  const i18nData = useMemo(() => PLACE_LIST_I18N[language] || PLACE_LIST_I18N.vi, [language]);

  useEffect(() => {
    let isMounted = true;

    const loadPlaces = async () => {
      setLoading(true);
      try {
        const data = await fetchLandingPlaces();
        if (isMounted) {
          setPlaces(Array.isArray(data) && data.length ? data : FALLBACK_PLACES);
        }
      } catch {
        if (isMounted) {
          setPlaces(FALLBACK_PLACES);
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    };

    loadPlaces();

    return () => {
      isMounted = false;
    };
  }, []);

  const categories = useMemo(() => {
    const categoryMap = new Map();
    places.forEach((place) => {
      const raw = String(place.category || '').trim();
      if (!raw) {
        return;
      }
      const key = raw.toLowerCase();
      if (!categoryMap.has(key)) {
        categoryMap.set(key, raw);
      }
    });

    return ['All', ...categoryMap.values()];
  }, [places]);

  const filteredPlaces = useMemo(() => {
    const keyword = searchTerm.trim().toLowerCase();
    return places.filter((place) => {
      const matchesCategory = activeCategory === 'All' || place.category === activeCategory;
      const matchesKeyword =
        !keyword ||
        place.name.toLowerCase().includes(keyword) ||
        String(place.district || '').toLowerCase().includes(keyword);
      return matchesCategory && matchesKeyword;
    });
  }, [places, searchTerm, activeCategory]);

  const resolvePlaceLink = (place) => {
    const lat = Number(place?.lat);
    const lng = Number(place?.lng);
    if (Number.isFinite(lat) && Number.isFinite(lng)) {
      return `${APP_ROUTES.CITY_MAP}?lat=${lat}&lng=${lng}`;
    }
    return `${APP_ROUTES.CITY_MAP}?city=da-nang`;
  };

  return (
    <section className={`place-list theme-${theme}`}>
      <div className="place-list-header">
        <div>
          <span className="place-list-kicker">Smart City Discovery</span>
          <h2>{i18nData.title}</h2>
          <p>{i18nData.subtitle}</p>
        </div>
        <Link to={APP_ROUTES.ALL_CITY} className="place-list-back">
          {i18nData.backButton}
        </Link>
      </div>

      <div className="place-list-controls">
        <input
          type="text"
          placeholder={i18nData.searchPlaceholder}
          value={searchTerm}
          onChange={(event) => setSearchTerm(event.target.value)}
        />
        <div className="place-list-categories">
          {categories.map((category) => (
            <button
              key={category}
              type="button"
              className={activeCategory === category ? 'active' : ''}
              onClick={() => setActiveCategory(category)}
            >
              {category === 'All' ? i18nData.allCategoriesLabel : category}
            </button>
          ))}
        </div>
      </div>

      {loading && <div className="place-list-loading">{i18nData.loadingText}</div>}

      {!loading && (
        <div className="place-list-grid">
          {filteredPlaces.map((place) => (
            <article key={place.id || place.name} className="place-list-card">
              <div className="place-list-image">
                <img
                  src={place.image || PLACE_IMAGE_BY_ID[place.id] || cityLandmark}
                  alt={place.name}
                  loading="lazy"
                />
              </div>
              <div className="place-list-body">
                <h3>{place.name}</h3>
                <p>{place.description}</p>
                <div className="place-list-meta">
                  <span>{place.category}</span>
                  {place.district && <span>{place.district}</span>}
                </div>
                <Link to={resolvePlaceLink(place)} className="place-list-cta">
                  {i18nData.exploreButton}
                </Link>
              </div>
            </article>
          ))}
        </div>
      )}
    </section>
  );
}

export default PlaceListPage;
